"""Build static, no-JavaScript-required startup pages from the curated catalogue."""
from pathlib import Path
from html import escape as e
import json
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'startups/projects.json').read_text())
def logo(p):
 return f'<img src="/assets/logos/{p["logo"]}" alt="Logo {p["name"]}" width="120" height="120">' if p['logo'] else '<span class="lettermark" aria-label="Oraculum">O.</span>'
def head(title,desc,path):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | Rafylsck Industries</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#111111"><link rel="canonical" href="https://rafylsckindustries.com.br{path}"><meta property="og:title" content="{e(title)} | Rafylsck Industries"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:image" content="https://rafylsckindustries.com.br/banner.png"><link rel="icon" href="/assets/icons/favicon-32.png"><link rel="stylesheet" href="/css/fonts.css?v=mono2"><link rel="stylesheet" href="/css/editorial.css?v=mono2"><link rel="stylesheet" href="/css/startups.css?v=1"><script src="/js/editorial.js?v=mono2" defer></script><script src="/js/startups.js?v=1" defer></script></head><body class="startups-site"><a class="skip" href="#conteudo">Pular para o conteúdo</a><header class="masthead"><div class="wrap header-row"><a class="wordmark" href="/" aria-label="Rafylsck Industries, início"><img src="/assets/logos/rafylsck-logo.png" alt=""><span>Rafylsck<small>INDUSTRIES</small></span></a><button class="menu" aria-controls="navigation" aria-expanded="false">Menu +</button><nav id="navigation" class="navigation" aria-label="Navegação principal"><a href="/startups/" aria-current="{ 'page' if path=='/startups/' else 'true' }">Startups</a><a href="/#pesquisa">Pesquisa</a><a href="/rafael/">Rafael Balceiro</a><a class="contact-link" href="#conversar">Vamos conversar ↗</a></nav></div></header>'''
def foot():
 return '''<section class="startup-contact wrap" id="conversar"><p class="eyebrow">Conexões que levam a próxima etapa</p><h2>Uma ideia em comum?<br><em>Vamos conversar.</em></h2><a class="pill" href="mailto:contato@rafylsckindustries.com.br">Falar com a Rafylsck <span>↗</span></a></section></main><footer class="footer"><div class="wrap footer-row"><span>© 2026 Rafylsck Industries · Ideias em construção.</span><div class="footer-links"><a href="/startups/">Startups</a><a href="/legal/privacy/">Privacidade</a><a href="/legal/terms/">Termos</a><a href="#conteudo">Voltar ao topo ↑</a></div></div></footer></body></html>'''
def mark(p):
 return f'<div class="startup-mark" style="--project:{p["color"]}">{logo(p)}<span class="mark-orbit" aria-hidden="true"></span></div>'
def card(p,i):
 return f'''<article class="startup-card" data-startup-category="{e(p['category'])}" style="--project:{p['color']}"><a href="/startups/{p['id']}/" aria-label="Conhecer {p['name']}"><div class="card-top"><span class="eyebrow">{i:02d} / {e(p['category'])}</span><span class="card-arrow" aria-hidden="true">↗</span></div>{mark(p)}<div class="card-copy"><span class="startup-status">{p['status']}</span><h3>{p['name']}</h3><p>{p['summary']}</p><span class="card-more">Explorar a startup <span aria-hidden="true">↗</span></span></div></a></article>'''
buttons=''.join(f'<button type="button" data-startup-filter="{e(c)}" aria-pressed="{str(i==0).lower()}">{c}</button>' for i,c in enumerate(['Todas']+list(dict.fromkeys(p['category'] for p in D))))
index=head('Startups','Conheça as startups e projetos da Rafylsck: Teseu, AutoZap, AnjoGuard, JuriX, AdHub, Oraculum e AutoBook.','/startups/')+f'''<main id="conteudo"><section class="startup-hero wrap"><div><p class="eyebrow">Rafylsck / Startup portfolio</p><h1>Ideias diferentes.<br>Uma vontade de<br><em>transformar.</em></h1><p class="startup-lead">Da rotina de uma loja ao cuidado com pessoas.<br>Explore os negócios que estamos construindo.</p><a class="pill" href="#portfolio">Conhecer as startups <span>↓</span></a></div><div class="hero-constellation" aria-label="Um ecossistema conectado de startups"><span class="constellation-ring" aria-hidden="true"></span><span class="constellation-ring inner" aria-hidden="true"></span><div class="constellation-core"><img src="/assets/logos/rafylsck-logo.png" alt="Rafylsck Industries" width="76" height="76"></div>{''.join(f'<a href="/startups/{p["id"]}/" class="constellation-node node-{i}" style="--project:{p["color"]}">{logo(p)}<span>{p["name"]}</span></a>' for i,p in enumerate(D))}<span class="constellation-caption">Diferentes caminhos. A mesma origem.</span></div></section><div class="portfolio-intro wrap"><span>07 projetos / Um ecossistema</span><p>Produtos, protótipos e pesquisa, cada um no seu momento.<br>Conheça a proposta e o estágio de cada iniciativa.</p></div><section class="wrap startup-portfolio" id="portfolio"><div class="portfolio-heading"><div><p class="eyebrow">Explore por interesse</p><h2>Encontre sua<br><em>próxima conexão.</em></h2></div><p>Escolha um projeto para conhecer sua visão,<br>suas possibilidades e os próximos passos.</p></div><div class="startup-filters" role="group" aria-label="Filtrar startups por área" hidden>{buttons}</div><p class="startup-result" aria-live="polite" hidden>7 projetos</p><div class="startup-grid">{''.join(card(p,i+1) for i,p in enumerate(D))}</div><div class="beyond"><span class="eyebrow">Além do portfólio</span><p>Pesquisa, automação e novas frentes também fazem parte dessa história.</p><a class="text-link" href="/rafael/#projetos">Ver todos os projetos ↗</a></div></section>'''+foot()
(R/'startups/index.html').write_text(index)
for i,p in enumerate(D):
 flow=''.join(f'<div><span>0{n+1}</span><h3>{e(f)}</h3></div>' for n,f in enumerate(p['flow']))
 photo=f'''<figure class="project-photo"><img src="/assets/startups/{p['photo']}" alt="{'Ilustração de uma loja de telefonia com a identidade AutoZap' if p['id']=='autozap' else 'Ilustração de uma tela publicitária em um café'}" width="1400" height="790" loading="lazy"><figcaption>Imagem ilustrativa do universo {p['name']}. Não representa um estabelecimento cliente.</figcaption></figure>''' if p.get('photo') else ''
 source=f'<a class="text-link" href="{p["source"]}">Consultar a apresentação do projeto ↗</a>' if p.get('source') else ''
 related=[D[(i+1)%len(D)],D[(i+2)%len(D)]]
 body=head(p['name'],p['summary'],f'/startups/{p["id"]}/')+f'''<main id="conteudo" style="--project:{p['color']}"><nav class="wrap startup-breadcrumb" aria-label="Caminho"><a href="/startups/">← Todas as startups</a><span>/ {p['name']}</span></nav><section class="wrap startup-detail-hero"><div><p class="eyebrow">{p['category']} / {p['name']}</p><h1>{p['headline']}</h1><p class="startup-lead">{p['summary']}</p><div class="actions"><a class="pill" href="#visao">Conhecer {p['name']} <span>↓</span></a><span class="startup-status">{p['status']}</span></div></div><div class="detail-brand">{mark(p)}<span class="detail-wordmark">{p['name']}</span></div></section><section class="wrap startup-story" id="visao"><div><p class="eyebrow">01 / A visão</p><h2>{p['name']}.<br><em>Por que existe?</em></h2></div><div><p class="story-lead">{p['about']}</p><p class="audience"><strong>Para quem</strong>{p['audience']}</p>{source}</div></section><section class="wrap startup-capabilities"><div><p class="eyebrow">02 / Possibilidades</p><h2>O que conecta<br><em>essa ideia.</em></h2></div><ul>{''.join(f'<li><span aria-hidden="true">↗</span>{e(f)}</li>' for f in p['features'])}</ul></section><section class="wrap journey-section"><p class="eyebrow">Uma visão da experiência</p><div class="startup-journey">{flow}</div><p class="journey-note">Fluxo conceitual. A disponibilidade dos recursos acompanha a evolução do projeto.</p>{photo}</section><aside class="wrap project-stage"><span class="eyebrow">Transparência / Estágio atual</span><h2>{p['status']}</h2><p>{p['note']}</p></aside><section class="wrap related-startups"><div class="portfolio-heading"><h2>Continue<br><em>explorando.</em></h2><a class="text-link" href="/startups/">Ver todas as startups ↗</a></div><div class="startup-grid related-grid">{''.join(card(r,D.index(r)+1) for r in related)}</div></section>'''+foot()
 folder=R/'startups'/p['id'];folder.mkdir(exist_ok=True);(folder/'index.html').write_text(body)
print(f'Built {len(D)+1} startup pages.')
